export const replacementRatioDefinitions={replacementRatio:{title:'Reconcile a current annual cash budget with one retirement-year spending scenario',fields:[
 ['replaceGross','Current gross annual employment pay (CAD)',100000,40000,200000,5000],
 ['replaceDeductions','Current tax and other pay deductions, excluding the saving entry (% of gross)',25,0,40,1],
 ['replaceSavings','Saving from take-home cash, expressed as a share of gross pay (%)',15,0,20,1],
 ['replaceWorkEnds','Current work costs assumed to end at retirement (% of gross pay)',5,0,10,1],
 ['replaceDebtEnds','Current debt payments assumed to end before retirement (% of gross pay)',10,0,15,1],
 ['replaceAdded','Additional annual retirement spending above the continuing budget (CAD)',5000,0,30000,1000],
 ['replaceRetireTax','Assumed average tax fraction on the modeled gross retirement receipts (%)',20,0,40,1],
 ['replaceChosen','Gross retirement receipt target as a share of current gross pay (%)',70,40,100,1]
]}};
export function replacementRatioPlan(d){
 const deductions=d.replaceGross*d.replaceDeductions/100,savings=d.replaceGross*d.replaceSavings/100,workEnds=d.replaceGross*d.replaceWorkEnds/100,debtEnds=d.replaceGross*d.replaceDebtEnds/100,ongoing=d.replaceGross-deductions-savings-workEnds-debtEnds,need=ongoing+d.replaceAdded,targetGross=need/(1-d.replaceRetireTax/100),chosenGross=d.replaceGross*d.replaceChosen/100,chosenTax=chosenGross*d.replaceRetireTax/100,chosenNet=chosenGross-chosenTax;
 return {deductions,savings,workEnds,debtEnds,ongoing,need,targetGross,targetRatio:targetGross/d.replaceGross,chosenGross,chosenTax,chosenNet,excess:chosenNet-need};
}
export function replacementRatioResult(kind,d){
 if(kind!=='replacementRatio')throw Error('Unknown retirement replacement-ratio topic.');
 const p=replacementRatioPlan(d);
 return {metrics:[['Retirement spending cash need',p.need,'money'],['Gross retirement receipts implied by the chosen tax fraction',p.targetGross,'money'],['Implied gross receipts as a share of current gross pay',p.targetRatio,'percent'],['Chosen gross ratio: cash excess (+) or gap (−)',p.excess,'money']],note:'Original hypothetical annual cash-budget reconciliation, with all amounts in one common price basis. It is a comparison of one working-year budget with one retirement-year budget, not a multi-year projection. Current deductions, take-home saving, ending work costs, ending debt payments and continuing cash needs are disjoint uses of gross pay. All four percentage inputs use current gross pay as their denominator. Current deductions exclude the saving entered separately. The residual continuing budget includes any debt service or work-related cost that will continue. The stated ending costs actually cease in this scenario, and the current saving transfer stops. Additional retirement spending is added to the continuing budget. Modeled retirement receipts are one assumed gross taxable cash stream with the same flat average tax fraction at every tested income. The tax fraction is an entered assumption, not a marginal tax bracket, a withholding rate or a calculation under current law. No pension entitlement, benefit reduction, payroll contribution rule, account-specific tax treatment, tax-free withdrawal, return of capital, spouse’s income, capital balance or withdrawal strategy is calculated. The gross ratio comparison first subtracts its assumed retirement tax, then compares net cash with spending. A positive difference is cash excess in this one-year budget, not proof that retirement is funded. Inflation between dates, longevity, changing spending phases, investment uncertainty, ongoing saving and large one-time costs require separate schedules. The input bounds keep the current continuing budget positive; the derived retirement gross ratio may exceed 100% and is not capped.',charts:[
  {id:'replacement-ratio-current-bridge',type:'waterfall',title:'Reconcile gross pay with the current cash needs that continue into retirement',unit:'money',unitLabel:'CAD per working year · mutually exclusive cash uses',rows:[{label:'Current gross employment pay',value:d.replaceGross},{label:'Tax and other pay deductions',value:-p.deductions},{label:'Saving from take-home cash',value:-p.savings},{label:'Work costs assumed to end',value:-p.workEnds},{label:'Debt payments assumed to end',value:-p.debtEnds}],totalLabel:'Continuing annual cash needs',note:'The residual is the current budget left after the four named uses of pay. Saving is a cash allocation, rather than current consumption. Debt payments can contain principal as well as interest; the whole payment must actually end before it can be removed from the retirement cash budget. Costs that continue belong in the residual instead.'},
  {id:'replacement-ratio-retirement-bridge',type:'waterfall',title:'Build the retirement spending amount before funding its income tax',unit:'money',unitLabel:'CAD of spending cash in one retirement year · common price basis',rows:[{label:'Continuing annual cash needs',value:p.ongoing},{label:'Additional retirement spending',value:d.replaceAdded}],totalLabel:'Retirement spending cash need',note:'This is the amount available to pay the modeled non-income-tax spending. The tax needed to obtain that cash from gross taxable receipts is calculated separately. The additional amount is incremental; do not include the same travel, care or household expense both in the continuing budget and in the addition.'},
  {id:'replacement-ratio-net-comparison',type:'signedbar',title:'Pass the chosen gross ratio through its tax assumption before comparing it with bills',unit:'money',unitLabel:'CAD in one retirement year · positive difference is cash excess',rows:[{label:'Net cash from chosen ratio',value:p.chosenNet},{label:'Retirement spending cash need',value:p.need},{label:'Cash excess (+) or gap (−)',value:p.excess}],note:'Gross receipts equal the chosen ratio multiplied by current gross pay. Net cash equals those receipts multiplied by one minus the assumed retirement tax fraction. The third bar subtracts spending need from that net cash; it is a difference, not a third income source. No asset balance or lifetime sustainability is inferred from it.'},
  {id:'replacement-ratio-budget-sensitivity',type:'heatmap',title:'The gross replacement ratio changes with spending and the tax assumption',unit:'percent',unitLabel:'Required gross retirement receipts ÷ current gross annual pay',tableUnit:'Percent of current gross pay',columns:['0% tax','10% tax','20% tax','30% tax'],rows:[0,5000,10000,20000].map(replaceAdded=>({label:replaceAdded?'Extra $'+replaceAdded/1000+'k':'No extra',values:[0,10,20,30].map(replaceRetireTax=>replacementRatioPlan({...d,replaceAdded,replaceRetireTax}).targetRatio)})),note:'Rows vary additional annual spending and columns vary the assumed average retirement tax fraction. Current gross pay and all four current budget shares stay fixed. The cells solve spending divided by one minus the tax fraction, then divide by current gross pay. They are conditional calculations, not published replacement-rate statistics, tax forecasts or recommended targets.'}
 ]};
}
